def icehl_schedule(
    season: int,
    league_id: int = 1,
    *,
    return_parsed: bool = True,
    return_as_pandas: bool = False,
    **kwargs,
) -> Union[pl.DataFrame, pd.DataFrame, Dict]:
    """Schedule and results of one competition season, one row per match, played or not.

    Endpoint: ``GET https://s3.eu-west-1.amazonaws.com/icehl.hokejovyzapis.cz/league-matches/{season}/{league_id}.json``
    Example URL: https://s3.eu-west-1.amazonaws.com/icehl.hokejovyzapis.cz/league-matches/2026/1.json

    Args:
        season: Season by its END year (2027 = 2026/27). The bucket keys seasons by their START year; the wrapper requests season - 1.
        league_id: Competition id. 1 = ICE Hockey League, regular season and playoffs in one file (split them by league_part_name); 2 = pre-season (2025/26 on).
        return_parsed: parse the payload through parse_esports_schedule -> polars DataFrame (default True). Pass return_parsed=False for the raw JSON Dict.
        return_as_pandas: with return_parsed, return a pandas DataFrame instead of polars.
        **kwargs: Forwarded to the underlying HTTP getter.

    Returns:
        A polars/pandas DataFrame by default; the raw JSON ``Dict`` when ``return_parsed=False``.

    Raises:
        NoDataError: The host answered 404 -- the requested resource does not exist. The bucket has no such key (S3 404 NoSuchKey: unknown season, competition, match or team), or the file holds no rows (an unplayed game, an empty shot shell).
        ValueError: The host answered 400 / 422 -- the request is wrong; retrying cannot help.
        AssetFetchError: The fetch failed (a non-2xx answer or a connection failure after retries, e.g. 401/403/429/5xx, or an empty or unreadable 200 body) -- the answer is unknown, not empty.

    Example:
        Quick start::

            from sportsdataverse.hockey.icehl import icehl_schedule
            icehl_schedule(league_id=1, season=2027)

        See Also:
            * `ICE Hockey League`_ - the league site whose widgets read this public eSports bucket

        .. _ICE Hockey League: https://www.ice.hockey/
    """
    _caller_params = kwargs.pop("params", None) or {}
    _params = {}
    _params.update(_caller_params)
    season = season_start_year(season)
    __url = f"https://s3.eu-west-1.amazonaws.com/icehl.hokejovyzapis.cz/league-matches/{season}/{league_id}.json"
    raw = _get(
        __url,
        params=_params,
        **kwargs,
    )
    if return_parsed:
        return parse_esports_schedule(raw, return_as_pandas=return_as_pandas, columns=_PARSER_COLUMNS["schedule"])
    return raw


